mapper.select:
select e.event_id, e.rule_id, r.rule_no, coalesce(r.del_flag = '2', false) as rule_deleted, e.metric_code, coalesce(c.metric_name, e.metric_code) as metric_name, c.value_format, e.level, e.escalated, e.status, e.start_hour, e.trigger_hour, e.end_hour, e.last_period_end, e.stopped_at, e.stop_reason, e.current_value, e.baseline_value, e.rule_snapshot::text as rule_snapshot, r.owner_user_id, ou.email as owner_email, e.notify_status, e.notified_at, e.mute_sent_at, e.mute_hours, case when e.notify_status = 'failed' then nl.error_msg end as notify_error, coalesce(nl.chat_id, nullif(e.rule_snapshot->>'notifyChatId', ''), r.notify_chat_id) as chat_id, coalesce(ch.name, nullif(e.rule_snapshot->>'notifyChatName', ''), r.notify_chat_name) as chat_name, ch.status as chat_status, e.handle_status, e.handle_note, coalesce(nullif(hu.email, ''), hu.user_name) as handled_by, e.handled_at, e.handle_reset from monitor_event e left join monitor_rule r on r.rule_id = e.rule_id and r.site_code = e.site_code left join dashboard_metric_card c on c.metric_code = e.metric_code left join sys_user ou on ou.user_id = r.owner_user_id left join sys_user hu on hu.user_id = e.handled_by left join lateral ( select n.chat_id, n.error_msg from monitor_notify_log n where n.event_id = e.event_id and n.site_code = e.site_code and n.chat_id is not null order by n.id desc limit 1) nl on true left join monitor_lark_chat ch on ch.site_code = e.site_code and ch.chat_id = coalesce(nl.chat_id, nullif(e.rule_snapshot->>'notifyChatId', ''), r.notify_chat_id) where e.event_type = 'alert'
and e.handle_status = #{q.handle}
and e.status = #{q.status}
and e.metric_code = #{q.metricCode}
and r.owner_user_id = #{q.ownerId}
and (e.status = 'open' or (e.trigger_hour >= #{q.rangeFrom} and e.trigger_hour < #{q.rangeTo}))
order by case when e.status = 'open' then 0 else 1 end, e.trigger_hour desc, e.metric_code asc, e.event_id desc
